import { useState } from 'react';

function Counter() {
  // [currentValue, setterFunction] = useState(initialValue)
  const [count, setCount] = useState(0);

  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>+1</button>
      <button onClick={() => setCount(count - 1)}>-1</button>
      <button onClick={() => setCount(0)}>Reset</button>
    </div>
  );
}

function EventDemo() {
  const handleClick = (event) => {
    console.log('Clicked!', event.target);
  };

  const handleChange = (event) => {
    console.log('Value:', event.target.value);
  };

  const handleSubmit = (event) => {
    event.preventDefault(); // stop page reload
    console.log('Submitted!');
  };

  return (
    <form onSubmit={handleSubmit}>
      {/* Pass function reference, not call */}
      <button onClick={handleClick}>Click Me</button>

      {/* Inline arrow for passing arguments */}
      <button onClick={() => handleClick('extra arg')}>With Arg</button>

      <input onChange={handleChange} />
      <button type="submit">Submit</button>
    </form>
  );
}

import { useState } from 'react';

function SignupForm() {
  const [form, setForm] = useState({
    name: '',
    email: '',
    password: ''
  });
  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = {};
    if (!form.name) newErrors.name = 'Name is required';
    if (!form.email.includes('@')) newErrors.email = 'Invalid email';
    if (form.password.length < 8) newErrors.password = 'Min 8 chars';

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    console.log('Valid form!', form);
  };

  return (
    <form onSubmit={handleSubmit}>
      <input name="name" value={form.name} onChange={handleChange}
             placeholder="Full name" />
      {errors.name && <span className="error">{errors.name}</span>}

      <input name="email" type="email" value={form.email}
             onChange={handleChange} placeholder="Email" />

      <input name="password" type="password" value={form.password}
             onChange={handleChange} placeholder="Password" />

      <button type="submit">Sign Up</button>
    </form>
  );
}

function UserDashboard({ user, isLoading, error }) {
  // Pattern 1: Early return for loading/error states
  if (isLoading) return <Spinner />;
  if (error) return <ErrorMessage message={error} />;
  if (!user) return null;

  return (
    <div>
      {/* Pattern 2: && short-circuit (use when you want nothing or something) */}
      {user.isAdmin && <AdminBadge />}

      {/* Pattern 3: Ternary (use when you want one thing OR another) */}
      {user.isPremium
        ? <PremiumBanner />
        : <UpgradeBanner />
      }

      {/* Pattern 4: Variable assignment for complex conditions */}
      {(() => {
        if (user.score >= 90) return <GoldTrophy />;
        if (user.score >= 70) return <SilverTrophy />;
        return <BronzeTrophy />;
      })()}
    </div>
  );
}

// ❌ Before: each component has its own state, can't share
function FilterBar() {
  const [query, setQuery] = useState('');
  // ...
}
function ProductList() {
  // Can't access FilterBar's query!
}

// ✅ After: lift state to shared parent
function ShopPage() {
  const [query, setQuery] = useState('');
  const [sortBy, setSortBy] = useState('name');

  return (
    <div>
      {/* Pass state DOWN, pass setters DOWN as callbacks */}
      <FilterBar query={query} onQueryChange={setQuery} sortBy={sortBy} onSortChange={setSortBy} />
      <ProductList query={query} sortBy={sortBy} />
    </div>
  );
}

function FilterBar({ query, onQueryChange }) {
  return (
    <input
      value={query}
      onChange={(e) => onQueryChange(e.target.value)}
      placeholder="Search products..."
    />
  );
}
